from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


_CENTS = Decimal("0.01")


def _is_deleted(row: dict[str, Any]) -> bool:
    return row.get("DEL_FLG") == "Y"


def _numeric(value: Any) -> Decimal:
    """Apply legacy NVL/numeric-context semantics."""
    if value is None:
        return Decimal("0")
    if isinstance(value, str) and value.strip() == "":
        return Decimal("0")
    return Decimal(str(value))


def _cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """
    Apply ORD-003 and the invoiced-order cancel workflow transition.

    The returned order is always a new dictionary; the supplied order is not mutated.
    """
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    result = dict(order)

    if new_status == "I":
        return result, [], []

    if new_status == "X":
        result["STAT_CD"] = "X"
        return result, ["ORD_CANC_INV"], ["credit_note"]

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """
    Recompute live line extensions and the header total.

    Invoiced and cancelled orders are frozen. Soft-deleted headers are excluded from
    the legacy nightly recompute, and soft-deleted lines are copied unchanged.
    """
    result_order = dict(order)
    result_lines = [dict(line) for line in lines]

    if _is_deleted(order) or order.get("STAT_CD") in {"I", "X"}:
        return result_order, result_lines, []

    total = Decimal("0")

    for original_line, result_line in zip(lines, result_lines):
        if _is_deleted(original_line):
            continue

        extension = _cents(
            _numeric(original_line.get("QTY"))
            * _numeric(original_line.get("UNIT_PRC"))
        )
        result_line["EXT_AMT"] = float(extension)
        total += extension

    discounted_total = _cents(
        total * (Decimal("100") - _numeric(order.get("DISC_PCT"))) / Decimal("100")
    )
    result_order["TOT_AMT"] = float(discounted_total)

    stored_total = _numeric(order.get("TOT_AMT"))
    audits = ["ORD_RETOTAL"] if stored_total != discounted_total else []

    return result_order, result_lines, audits
